            cpu->pbr = 0xC2u;
            cpu->pc = 0x8BF2u;
            if (nh_scpu_expect_next(cpu, 0x06145F90u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
            return nh_scpu_finish(cpu, bus, (4u) + ((cpu->d & 0x00FFu) != 0u ? 1u : 0u));
