            if ((result & 0x8000u) != 0u) cpu->p |= NH_P_N;
            cpu->pbr = 0xC2u;
            cpu->pc = 0x8BFBu;
            if (nh_scpu_expect_next(cpu, 0x06145FD8u) != NH_SCPU_EXECUTED)
                return NH_SCPU_STOPPED;
